const BIDRIWARE_INFO={id:"bidriware-craftsmanship",title:"Bidriware Handicraft & Metal Inlay",originRegion:"Bidar, Karnataka",eraOrigin:"14th Century CE (Bahmani Sultanate)",giTagStatus:"Geographical Indication (GI) Certified",alloyComposition:"Zinc (95%) & Copper (5%) Alloy Base",inlayMaterial:"Pure Silver Wire (99.9%) & Gold Leaf",specialElement:"Blackening soil sourced exclusively from Bidar Fort",quickStats:[{label:"GI Tag Certified",value:"Bidar, Karnataka",icon:"🏷️"},{label:"Base Alloy",value:"95% Zinc + 5% Copper",icon:"🪙"},{label:"Inlay Metal",value:"Pure Silver (99.9%)",icon:"✨"},{label:"Blackening Agent",value:"Bidar Fort Soil",icon:"🏺"},{label:"Origin Era",value:"Bahmani Kings (14th C)",icon:"👑"},{label:"Techniques",value:"Tarkashi & Taiyabi",icon:"✍️"}]},PROCESS_STEPS=[{step:1,title:"Mold Casting",description:"Artisans melt zinc and copper ingot alloy, pouring liquid metal into custom clay-and-resin sand molds."},{step:2,title:"Chiseling & Chasing",description:"The smooth cast metal object is coated with copper sulphate to turn dark temporary grey, allowing master engravers to etch intricate geometric patterns using fine steel chisels."},{step:3,title:"Silver Inlay (Tarkashi / Taiyabi)",description:"Pure silver wires or thin sheet foils are hammered delicately into the carved grooves using small brass hammers."},{step:4,title:"Sanding & Polishing",description:"The object surface is buffed smooth with fine emery paper to level the embedded silver flush against the alloy."},{step:5,title:"Bidar Fort Soil Oxidation",description:"The artifact is boiled in a solution of ammonium chloride and soil collected from unexposed areas of Bidar Fort; the zinc oxidizes into jet-black while pure silver shines brilliantly white."}],TRADITIONAL_MOTIFS=[{name:"Phool Ladi (Floral Garland)",description:"Flowing floral creepers and lotus petals inspired by Persian and Deccani miniature paintings."},{name:"Ashrafi Boti (Gold Coin Motif)",description:"Repeating circular coin and star motifs symbolic of royal prosperity and Bahmani court elegance."},{name:"Jali & Arabesque Patterns",description:"Complex geometric latticework mimicking carved sandstone screens of Bidar Fort and Mahmud Gawan Madrasa."},{name:"Paisley / Kalka Motifs",description:"Classic mango-leaf motifs delicately inlaid with fine silver wire along vase rims and hookah bases."}],ARTISAN_COMMUNITY={title:"Bidar Heritage Guilds",description:"Centuries of royal patronage by Sultan Ahmad Shah Bahmani established Bidar as India's sole authentic center for Bidri craft. Today, over 500 hereditary artisan families continue this mastercraft under the Bidriware Artisans Welfare Association."},GALLERY_IMAGES=[{url:"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a2/Bidriware_vase.jpg/800px-Bidriware_vase.jpg",caption:"Antique Bidriware vase featuring silver Tarkashi floral inlay work",category:"Artifact"},{url:"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c2/Bidar_Fort_Karnataka.jpg/800px-Bidar_Fort_Karnataka.jpg",caption:"Bidar Fort — Source of the unique nitrate-rich blackening soil used in oxidation",category:"Heritage"}],REFERENCES=[{text:"Karnataka State Handicrafts Development Corporation — Bidriware GI Specification.",link:"#"},{text:"Stronge, Susan (1985). Bidri Ware: Inlaid Metalwork from India. Victoria and Albert Museum.",link:"#"},{text:"National Handicrafts Development Programme — Bidar Craft Cluster.",link:"https://handicrafts.nic.in"}];"undefined"!=typeof module&&module.exports&&(module.exports={BIDRIWARE_INFO:BIDRIWARE_INFO,PROCESS_STEPS:PROCESS_STEPS,TRADITIONAL_MOTIFS:TRADITIONAL_MOTIFS,ARTISAN_COMMUNITY:ARTISAN_COMMUNITY,GALLERY_IMAGES:GALLERY_IMAGES,REFERENCES:REFERENCES});